
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_ernzerhof_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_ernzerhof", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.401185008527092e+01, 9.036119656856725e+01, 8.537014303072728e+01, 7.869628244080671e+01, 7.005143088344865e+01, 5.935070618427658e+01, 4.693477222910070e+01, 3.379234458141300e+01, 2.157691921561171e+01, 1.208467245481742e+01, 5.845893774738077e+00, 2.554993731198999e+00, 1.907277395789255e+00, 1.268609045798954e+00, 6.602158008943205e-01, 3.124623207293312e-01, 2.653358434012716e-01, 4.682831745184644e-01, 5.912317295329840e-01, 5.741916453809629e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


